import{bV as s,aL as n,u as e,G as p}from"./chunks/framework.O9JQzcbi.js";const m=JSON.parse('{"title":"模板编辑器：架构","description":"实现一个模板编辑器","frontmatter":{"title":"模板编辑器：架构","date":"2024-10-27T16:00:03.000Z","top":true,"categories":["Vue"],"description":"实现一个模板编辑器","tags":["Vue","编辑器","架构"]},"headers":[],"relativePath":"log/vue/template_editor_guide.md","filePath":"log/vue/template_editor_guide.md","lastUpdated":1789838113000}'),l={name:"log/vue/template_editor_guide.md"};function i(t,a,o,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /log/vue/template_editor_guide.md for this page in Markdown format</div><h1 id="模板编辑器-架构" tabindex="-1">模板编辑器：架构 <a class="header-anchor" href="#模板编辑器-架构" aria-label="Permalink to &quot;模板编辑器：架构&quot;">​</a></h1><p>编辑器，这个词听起来就挺高大上的，事实确实也不那么简单</p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>这篇文章是编辑器写完后的接近一年 才想起来要打算写一篇文章记录。编辑器于22年12月11日开始写 直到 23年3月底写完。23年回想起来太难了，差点结束程序员👨🏻‍💻生涯 哎。。。太难了。。。</p><p>写编辑器的动机起初是公司内有一个模板编辑器模块，看上去确实挺强的，实现的功能有对齐辅助线、缩放、属性编辑、撤销、重做、历史记录，保存为模板可以使用模板根据控件绑定的字段可以填充数据渲染并导出pdf打印。大致看了下模块代码，发现有些地方写的并不够清晰，比较乱，如果后续交由我来维护可能到时候有些摸不着北。但是代码组织还是不错，模板控件的设计很有条理，是可以学到不少东西。</p><p>不巧23年春节公司放假最后一天，把我裁了。。。22年7月20才刚刚进去。。。23年春节后回来就开始投简历，发现投下去基本上很多是已读未回或者未读，要么就是明确拒绝大专，必须本科+以上。。。</p><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/202410271800925.gif" alt=""></p><p>失业后，想着自从17年5月入行到23年也有5年半了，总觉得自己仿佛是到了一个瓶颈，无法突破，投简历又始终没有面试邀约，心态逐渐发生了变化有些着急，想着不如趁着这个时期静下心来提升自己。遂想着试着仿写前公司的模板编辑器。</p><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>模板编辑器是一个类似word的编辑器，但是不能手动添加文本等等，必须使用内置的控件来生成特定场景下的模板。例如医院的病例报告，可能不同的科室上有不同的特定病因名词，又或者要展示某个病因，则需要开发对应的控件。</p><p>今天这个模板编辑器没有实现那么复杂的控件，但是核心模块实现其实这些也就达到目的了</p><p><em>说明：目前编辑器只实现了前端部分，没有涉及到后端填充数据，所以也就没有绑定数据key等逻辑</em></p><h2 id="需求分析" tabindex="-1">需求分析 <a class="header-anchor" href="#需求分析" aria-label="Permalink to &quot;需求分析&quot;">​</a></h2><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/202410281534536.png" alt="template_editor"></p><ol><li>支持拖拉添加控件</li><li>控件可拖拉移动</li><li>控件拖拉时显示对齐辅助线</li><li>控件可被组合</li><li>撤销重做&amp;历史记录</li><li>字体，字体大小、边框、尺寸、属性修改，是否显示下划线、虚线</li><li>模板可支持预览</li><li>画布可支持修改：尺寸、方向、边距</li><li>画布支持缩放</li><li>画布支持拖拉</li><li>模板支持预览</li></ol><h3 id="原型" tabindex="-1">原型 <a class="header-anchor" href="#原型" aria-label="Permalink to &quot;原型&quot;">​</a></h3><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/1730276804.png" alt=""></p><h3 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to &quot;整体架构&quot;">​</a></h3><p><img src="https://static-1256180570.cos.ap-nanjing.myqcloud.com/image/1730276834.png" alt="模板编辑器应用架构"></p><h2 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h2><p>编辑器采用<code>Vue2.7.14</code> + <code>ES6+</code> + <code>SCSS</code> + <code>PUG</code> 开发，之所以没用 <code>Vue3</code> 是应为我当时还不会 <code>Vue3</code>，手动狗头</p><p>其主要目的是学习 <code>组合式api</code>，从而后面可以平滑过渡到 <code>Vue3</code></p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./src/views/template</span></span>
<span class="line"><span>├── action</span></span>
<span class="line"><span>│   ├── image</span></span>
<span class="line"><span>│   │   └── sprite.svg</span></span>
<span class="line"><span>│   ├── index.vue  --------------------- 模板编辑器入口</span></span>
<span class="line"><span>│   ├── template-aside.vue ------------- 模板编辑器左边栏（控件栏）模块</span></span>
<span class="line"><span>│   ├── template-editor.vue ------------ 模板编辑器模块</span></span>
<span class="line"><span>│   ├── template-property-option.vue --- 模板编辑器特殊属性模块</span></span>
<span class="line"><span>│   ├── template-property.vue ---------- 模板编辑器控件属性模块</span></span>
<span class="line"><span>│   ├── template-stage.vue ------------- 模板编辑器画布</span></span>
<span class="line"><span>│   └── template-toolbar.vue ----------- 模板编辑器工具栏</span></span>
<span class="line"><span>├── components ------------------------- 模板编辑器组件</span></span>
<span class="line"><span>│   ├── builtin ------------------------ 内置控件</span></span>
<span class="line"><span>│   │   ├── builtin-group.vue ---------- 内置控件-组</span></span>
<span class="line"><span>│   │   ├── builtin-input.vue ---------- 内置控件-输入框</span></span>
<span class="line"><span>│   │   ├── builtin-select.vue --------- 内置控件-下拉选择</span></span>
<span class="line"><span>│   │   ├── index.js</span></span>
<span class="line"><span>│   │   └── mixins --------------------- 控件公共props逻辑</span></span>
<span class="line"><span>│   │       └── index.js</span></span>
<span class="line"><span>│   ├── template-area.vue -------------- 模板编辑器框选组件(核心组件)</span></span>
<span class="line"><span>│   ├── template-contextmenu.vue ------- 模板编辑器右键菜单组件</span></span>
<span class="line"><span>│   ├── template-control.vue ----------- 模板编辑器控件拖拉组件(核心组件)</span></span>
<span class="line"><span>│   ├── template-document -------------- 模板编辑器文档模式(不可编辑控件，但是可对控件进行，输入或者选择值，设置预设值)</span></span>
<span class="line"><span>│   │   ├── index.js</span></span>
<span class="line"><span>│   │   └── render.vue</span></span>
<span class="line"><span>│   ├── template-mark-line.vue --------- 模板编辑器辅助线组件(纯渲染) 辅助线实现逻辑需要看  hooks/useMarkLine.js</span></span>
<span class="line"><span>├── constant.js ------------------------ 模板常量(事件名称)</span></span>
<span class="line"><span>├── hooks ------------------------------ 模板hooks</span></span>
<span class="line"><span>│   ├── useBorder.js ------------------- 计算边距大小(因为使用的是mm,所以需要转为px)</span></span>
<span class="line"><span>│   ├── useBuiltin.js ------------------ 使用内置控件(编辑器侧边栏展示的控件)</span></span>
<span class="line"><span>│   ├── useMarkLine.js ----------------- 提供计算辅助线显示隐藏和自动对齐功能</span></span>
<span class="line"><span>│   ├── usePadding.js ------------------ 画布边距</span></span>
<span class="line"><span>│   ├── useProperty.js ----------------- 初始化内置组件属性</span></span>
<span class="line"><span>│   ├── useRecord.js ------------------- 提供历史记录功能</span></span>
<span class="line"><span>│   ├── useSetting.js ------------------ 提供预设内置组件特殊属性配置</span></span>
<span class="line"><span>│   ├── useSize.js --------------------- 预设画布尺寸</span></span>
<span class="line"><span>│   ├── useStore.js -------------------- 编辑器全局状态(核心功能)</span></span>
<span class="line"><span>│   └── useToHtml.js ------------------- 将模板转为普通HTML预览展示</span></span>
<span class="line"><span>└── utils</span></span>
<span class="line"><span>    ├── index.js ----------------------- 工具函数库，包含自定义事件创建组件&amp;组，删除组，属性类，获取组件在画布内的位置，格式化控件属性</span></span>
<span class="line"><span>    └── record.js ---------------------- 历史记录日志打印</span></span>
<span class="line"><span></span></span>
<span class="line"><span>8 directories, 36 files</span></span></code></pre></div><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>我的文字功底一直很差😅，上学时候写作文作文编都不会编，将就着读，见谅见谅。有问题留言我会一一解答</p>`,27)])])}const h=s(l,[["render",i]]);export{m as __pageData,h as default};
